function verifyChat(token){
  const crypto = require('crypto');
  const SECRET = 'yavibot-dev-secret-change-me';
  if(!token) return null;
  const parts = String(token).split('.');
  if(parts.length !== 3) return null;
  const [h,p,s] = parts;
  const b64 = b => Buffer.from(b).toString('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
  if(b64(crypto.createHmac('sha256', SECRET).update(h+'.'+p).digest()) !== s) return null;
  let c; try { c = JSON.parse(Buffer.from(p.replace(/-/g,'+').replace(/_/g,'/'),'base64').toString()); } catch(e){ return null; }
  if(c.typ !== 'chat') return null;
  if(c.exp && c.exp < Math.floor(Date.now()/1000)) return null;
  return c;
}

const { Client } = require('pg');
const nodemailer = require('nodemailer');
const claims = verifyChat($json.headers['x-chat-session'] || $json.headers['X-Chat-Session']);
if(!claims) return [{ json: { _status:401, _body:{ ok:false, error:{ code:'NO_AUTENTICADO', message:'Sesión de chat no válida' } } } }];
const body = $json.body || {};
const tipoCod = String(body.tipo || '');
const descripcion = body.descripcion ? String(body.descripcion) : null;

const client = new Client({host:'postgres',port:5432,user:'yavibot',password:'yavibot_dev_2026',database:'yavibot'});
await client.connect();
try {
  const est = (await client.query(
    'SELECT id, carrera_id, nivel, paralelo FROM estudiantes WHERE cedula = $1', [claims.sub])).rows[0];
  if(!est) return [{ json: { _status:404, _body:{ ok:false, error:{ code:'NO_ENCONTRADO', message:'Estudiante no encontrado' } } } }];
  const tipo = (await client.query(
    'SELECT id, ambito, genera_ticket FROM tipos_solicitud WHERE codigo = $1', [tipoCod])).rows[0];
  if(!tipo || !tipo.genera_ticket)
    return [{ json: { _status:400, _body:{ ok:false, error:{ code:'VALIDACION', message:'Tipo de solicitud inválido' } } } }];

  // Crear ticket (código TK-000000 derivado del id)
  const ins = (await client.query(
    `INSERT INTO tickets (codigo, tipo_solicitud_id, estudiante_id, carrera_id, nivel, paralelo, descripcion, estado)
     VALUES ('TMP', $1, $2, $3, $4, $5, $6, 'Pendiente') RETURNING id`,
    [tipo.id, est.id, est.carrera_id, est.nivel, est.paralelo, descripcion])).rows[0];
  const codigo = 'TK-' + String(ins.id).padStart(6, '0');
  await client.query('UPDATE tickets SET codigo = $1 WHERE id = $2', [codigo, ins.id]);

  // Responsables = usuarios activos cuyo ROL audita este trámite (rol_tipos_solicitud)
  const responsables = (await client.query(
    `SELECT u.id, u.nombres, u.correo FROM usuarios_panel u
       JOIN rol_tipos_solicitud rt ON rt.rol_id = u.rol_id
     WHERE rt.tipo_solicitud_id = $1 AND u.activo = true ORDER BY u.id`, [tipo.id])).rows;
  const responsable = responsables[0] || null;
  if(responsable) await client.query('UPDATE tickets SET responsable_id = $1 WHERE id = $2', [responsable.id, ins.id]);

  await client.query(
    'INSERT INTO ticket_historial (ticket_id, estado_nuevo, usuario_id) VALUES ($1, $2, $3)',
    [ins.id, 'Pendiente', responsable ? responsable.id : null]);

  // Eventos (outbox EDA)
  await client.query("INSERT INTO eventos (tipo, payload, origen) VALUES ($1, $2, 'chatbot')",
    ['TicketCreado', JSON.stringify({ ticket_id: ins.id, codigo, tipo: tipoCod })]);
  if(responsable) await client.query("INSERT INTO eventos (tipo, payload, origen) VALUES ($1, $2, 'chatbot')",
    ['TicketAsignado', JSON.stringify({ ticket_id: ins.id, responsable_id: responsable.id })]);

  // Avisar por correo a todos los responsables de ese rol
  if(responsables.length) {
    const _rawtx = nodemailer.createTransport({ host: $env.SMTP_HOST, port: Number($env.SMTP_PORT||465), secure: String($env.SMTP_SECURE||'true')!=='false', auth: $env.SMTP_USER ? { user: $env.SMTP_USER, pass: $env.SMTP_PASS } : undefined, tls: { rejectUnauthorized: false } }); const tx = { sendMail: async (m) => { try { return await _rawtx.sendMail(m); } catch(e) { console.log('YaviBot: correo no enviado -', e.message); } } };
    const f = (await client.query(
      `SELECT to_char(now() AT TIME ZONE 'America/Guayaquil','DD/MM/YYYY') AS fecha,
              to_char(now() AT TIME ZONE 'America/Guayaquil','HH24:MI')    AS hora`)).rows[0];
    const est2 = (await client.query(
      `SELECT e.nombres, e.cedula, e.correo, c.nombre AS carrera, ts.nombre AS tramite
         FROM estudiantes e JOIN carreras c ON c.id = e.carrera_id, tipos_solicitud ts
        WHERE e.id = $1 AND ts.id = $2`, [est.id, tipo.id])).rows[0];
    for(const r of responsables) {
      await tx.sendMail({ from: ($env.SMTP_FROM || $env.SMTP_USER || 'no-reply@yavibot.local'), to: r.correo,
        subject:`Nuevo ticket ${codigo} — ${est2.tramite}`,
        text:`Hola ${r.nombres},\n\nSe ha registrado un nuevo trámite que le corresponde atender.\n\n`+
             `Ticket:      ${codigo}\nTrámite:     ${est2.tramite}\n`+
             `Solicitante: ${est2.nombres} (C.I. ${est2.cedula})\n`+
             `Carrera:     ${est2.carrera}\nFecha:       ${f.fecha}\nHora:        ${f.hora}\n`+
             (descripcion ? `Detalle:     ${descripcion}\n` : '')+
             `\nIngrese al panel para gestionarlo.\n\nInstituto Superior Tecnológico Yavirac` });
    }
  }
  return [{ json: { _status:200, _body:{ ok:true, data:{ codigo, estado:'Pendiente' } } } }];
} finally { await client.end(); }
